"use client"

import { inknut } from "@/app/fonts"
import Tag from "@/components/onboarding/Tag"

import LinkIcon from "@/components/icons/LinkIcon"
import HomeIcon from "@/components/icons/HomeIcon"
import ShopIcon from "@/components/icons/ShopIcon"
import InstagramIcon from "@/components/icons/InstagramIcon"
import XIcon from "@/components/icons/XIcon"
import FacebookIcon from "@/components/icons/FacebookIcon"
import TumblrIcon from "@/components/icons/TumblrIcon"
import PixivIcon from "@/components/icons/PixivIcon"
import BlueskyIcon from "@/components/icons/BlueskyIcon"

type Vend = {
  name: string
  year?: string
}

type SocialLinks = Partial<{
  link: string
  home: string
  shop: string
  instagram: string
  x: string
  facebook: string
  tumblr: string
  pixiv: string
  bluesky: string
}>

type Props = {
  businessName: string
  displayName: string
  profileImageUrl?: string
  merchTags: string[]
  previousVends: Vend[]
  locationText: string
  email: string
  socials?: SocialLinks
}

function SocialIcon({
  href,
  label,
  children,
}: {
  href?: string
  label: string
  children: React.ReactNode
}) {
  if (!href) return null

  return (
    <a
      href={href}
      aria-label={label}
      target="_blank"
      rel="noreferrer"
      className="w-[24px] h-[24px] flex items-center justify-center hover:opacity-80"
    >
      {/* If your SVGs don’t obey size, we wrap them */}
      <span className="w-[24px] h-[24px] flex items-center justify-center">
        {children}
      </span>
    </a>
  )
}

export default function ProfileSidebar({
  businessName,
  displayName,
  profileImageUrl,
  merchTags,
  previousVends,
  locationText,
  email,
  socials,
}: Props) {
  return (
    <aside
      className="
        relative
        w-[316px] h-[982px]
        bg-white
        px-[20px] py-[40px]
        flex flex-col
        items-center
      "
    >
      {/* Watermark logo (Figma: centered, top: 30px, opacity 0.5) */}
      <div className="absolute top-[30px] left-1/2 -translate-x-1/2 opacity-50 pointer-events-none z-[1]">
        <span className={`${inknut.className} text-[18.1193px] tracking-[-0.02em] font-semibold text-[#262626]`}>
          konfolio
        </span>
      </div>

      {/* This wrapper centers the whole profile content block within the sidebar height */}
      <div className="flex-1 min-h-0 w-full flex items-center justify-center">
        {/* Profile block (Figma: w 276, gap 30) */}
        <div className="w-[276px] flex flex-col items-center gap-[30px]">
          {/* Image & Names (Figma: gap 12) */}
          <div className="w-full flex flex-col items-center gap-[12px]">
            <div className="w-[189px] h-[189px] rounded-[15px] overflow-hidden bg-[#A5A5A5]/10">
              {profileImageUrl ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={profileImageUrl}
                  alt="Profile picture"
                  className="w-full h-full object-cover"
                />
              ) : null}
            </div>

            <p className="m-0 w-full text-center font-inter font-normal text-[22px] leading-[27px] text-[#262626]">
              {businessName}
            </p>

            <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
              {displayName}
            </p>
          </div>

          {/* Social Medias: ONLY render icons that exist */}
          <div className="w-full h-[24px] flex items-center justify-center gap-[10px]">
            <SocialIcon href={socials?.link} label="Link">
              <LinkIcon />
            </SocialIcon>
            <SocialIcon href={socials?.home} label="Home">
              <HomeIcon />
            </SocialIcon>
            <SocialIcon href={socials?.shop} label="Shop">
              <ShopIcon />
            </SocialIcon>
            <SocialIcon href={socials?.instagram} label="Instagram">
              <InstagramIcon />
            </SocialIcon>
            <SocialIcon href={socials?.x} label="X">
              <XIcon />
            </SocialIcon>
            <SocialIcon href={socials?.facebook} label="Facebook">
              <FacebookIcon />
            </SocialIcon>
            <SocialIcon href={socials?.tumblr} label="Tumblr">
              <TumblrIcon />
            </SocialIcon>
            <SocialIcon href={socials?.pixiv} label="Pixiv">
              <PixivIcon />
            </SocialIcon>
            <SocialIcon href={socials?.bluesky} label="Bluesky">
              <BlueskyIcon />
            </SocialIcon>
          </div>

          {/* Merch Tags */}
          <div className="w-full flex flex-wrap justify-center gap-[10px]">
            {merchTags.map((t) => (
              <Tag key={t} label={t} />
            ))}
          </div>

          {/* Previous Vends (with italic gray year at 12px) */}
          <div className="w-full flex flex-col items-center gap-[12px]">
            <p className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5]">
              Previous Vends
            </p>

            {previousVends.map((vend, i) => (
              <p
                key={`${vend.name}-${i}`}
                className="m-0 w-full text-center font-inter font-normal text-[15px] leading-[140%] text-[#262626]"
              >
                {vend.name}
                {vend.year ? (
                  <span className="ml-[6px] font-inter italic font-normal text-[12px] leading-[140%] text-[#A5A5A5]">
                    {vend.year}
                  </span>
                ) : null}
              </p>
            ))}
          </div>

          {/* Aside */}
          <div className="w-full flex flex-col items-center gap-[12px]">
            <div className="flex items-center justify-center gap-[5px]">
              {/* placeholder location icon; swap to your real one later */}
              <span className="w-[12px] h-[12px] bg-[#A5A5A5] rounded-[2px]" />
              <p className="m-0 font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5] text-center">
                {locationText}
              </p>
            </div>

            <p className="m-0 font-inter font-normal text-[15px] leading-[140%] text-[#A5A5A5] text-center">
              {email}
            </p>
          </div>
        </div>
      </div>
    </aside>
  )
}
